def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True 
def solution(arr):
    for index, value in enumerate(arr):
        i = int(value)
        is_index_prime = is_prime(index)
        is_value_prime = is_prime(i)
        if is_index_prime != is_value_prime:
            return False
    return True
t = int(input())
for _ in range(t):
    arr = input()
    if solution(arr):
        print("YES")
    else:
        print("NO")

